// ---- Settings ----

export interface PctSettings {
	prioritizeReopen: boolean
	suppressIsolationInfo: boolean
}

// ---- Browser API types ----

export interface ContextualIdentity {
	name: string
	cookieStoreId: string
	icon: string
	iconUrl?: string
	color: string
	colorCode?: string
}

export interface Tab {
	id?: number
	url?: string
	index: number
	title?: string
	cookieStoreId?: string
	windowId?: number
}

export interface MenusOnClickInfo {
	menuItemId: string
	parentMenuItemId?: string
	linkUrl?: string
	bookmarkId?: string
}

export interface MenusOnShownInfo {
	contexts: string[]
	tabId?: number
}

export interface TabChangeInfo {
	status?: string
	url?: string
	cookieStoreId?: string
}

export interface ExtensionIcon {
	size: number
	url: string
}

export interface ExtensionInfo {
	id: string
	name: string
	enabled: boolean
	type: string
	icons?: ExtensionIcon[]
}

export interface MenusCreateDetails {
	id?: string
	title?: string
	contexts?: string[]
	parentId?: string
	type?: 'normal' | 'separator' | 'radio' | 'checkbox'
	checked?: boolean
	enabled?: boolean
	icons?: Record<number, string>
}

export interface ManagementApi {
	get(extensionId: string): Promise<ExtensionInfo>
}

export interface RuntimeApi {
	sendMessage(extensionId: string, message: Record<string, unknown>): Promise<unknown>
	getURL(path: string): string
}

export interface MenusApi {
	create(details: MenusCreateDetails): Promise<void>
	refresh(): Promise<void>
	removeAll(): Promise<void>
	onShown: {
		addListener(listener: (info: MenusOnShownInfo, tab: Tab) => void | Promise<void>): void
	}
	onHidden: {
		addListener(listener: () => void | Promise<void>): void
	}
	onClicked: {
		addListener(listener: (info: MenusOnClickInfo, tab?: Tab) => void | Promise<void>): void
	}
}

export interface TabsApi {
	create(details: { cookieStoreId?: string; url?: string; index?: number; windowId?: number; active?: boolean }): Promise<Tab>
	remove(tabId: number): Promise<void>
	get(tabId: number): Promise<Tab>
	move(tabId: number, moveProperties: { windowId?: number; index: number }): Promise<Tab>
