import type { BrowserApi, LoggerLike, Tab } from '../models'
import { TEMP_CONTAINERS_EXTENSION_IDS } from '../constants'

export interface TcLayerDeps {
	readonly browserApi: BrowserApi
	readonly logger: LoggerLike
}

export interface TcLayer {
	readonly extensionId: string | null
	/** 16-px icon URL for the TC extension itself, or null if TC is not installed. */
	readonly iconUrl: string | null
	isPresent(): boolean
	initialize(): Promise<void>
	isTempContainer(cookieStoreId: string): Promise<boolean>
	createTempContainer(url: string, index: number, windowId: number): Promise<Tab>
}

export class TcLayerImpl implements TcLayer {
	private readonly browserApi: BrowserApi
	private readonly logger: LoggerLike
	private _extensionId: string | null = null
	private _iconUrl: string | null = null

	constructor(deps: TcLayerDeps) {
		this.browserApi = deps.browserApi
		this.logger = deps.logger
	}

	get extensionId(): string | null {
		return this._extensionId
	}

	get iconUrl(): string | null {
		return this._iconUrl
	}

	isPresent(): boolean {
		return this._extensionId !== null
	}

	async initialize(): Promise<void> {
		for (const extensionId of TEMP_CONTAINERS_EXTENSION_IDS) {
			try {
				const extensionInfo = await this.browserApi.management.get(extensionId)
				if (extensionInfo.enabled) {
					this._extensionId = extensionId
					const icon = extensionInfo.icons?.find(i => i.size === 16) ?? extensionInfo.icons?.[0]
					this._iconUrl = icon?.url ?? null
					this.debug('Temporary Containers detected:', extensionInfo.name, extensionId)
					return
				}
			} catch {
				// Extension not installed — try next
			}
		}
		this._extensionId = null
		this.debug('No Temporary Containers extension found')
	}

	async isTempContainer(cookieStoreId: string): Promise<boolean> {
		if (!this._extensionId) return false
		try {
			return await this.browserApi.runtime.sendMessage(
				this._extensionId,
				{ method: 'isTempContainer', cookieStoreId },
			) as boolean
		} catch {
			return false
		}
	}

	async createTempContainer(url: string, index: number, windowId: number): Promise<Tab> {
		if (!this._extensionId) throw new Error('No Temporary Containers extension detected')
		const tab = await this.browserApi.runtime.sendMessage(this._extensionId, {
			method: 'createTabInTempContainer',
			url,
			active: true,
		})
		return tab as Tab
	}

	private debug(...args: unknown[]): void {
		this.logger.log(...args)
	}
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { MenuHandlerImpl } from '../src/background/menuHandler'
import type { BrowserApi, Tab } from '../src/models'
import type { TcLayer } from '../src/background/tcLayer'
import type { TabReopener } from '../src/background/tabReopener'
import { MENU_BOOKMARK_OPEN_NEW, MENU_LINK_OPEN_NEW, MENU_OPEN_NEW, MENU_REOPEN, NO_CONTAINER, TEMP_CONTAINER_SENTINEL } from '../src/constants'

function makeBrowserApi(): BrowserApi {
	return {
		menus: {
			create: vi.fn().mockResolvedValue(undefined),
			removeAll: vi.fn().mockResolvedValue(undefined),
			refresh: vi.fn().mockResolvedValue(undefined),
			onShown: { addListener: vi.fn() },
			onHidden: { addListener: vi.fn() },
			onClicked: { addListener: vi.fn() },
		},
		tabs: {
			create: vi.fn().mockResolvedValue({ id: 99, index: 0 }),
			remove: vi.fn().mockResolvedValue(undefined),
			get: vi.fn(),
			query: vi.fn().mockResolvedValue([]),
			update: vi.fn().mockResolvedValue({ id: 99, index: 0 }),
			onUpdated: { addListener: vi.fn() },
		},
		contextualIdentities: {
			query: vi.fn().mockResolvedValue([]),
			get: vi.fn(),
		},
		storage: {
			local: {
				get: vi.fn().mockResolvedValue({}),
				set: vi.fn().mockResolvedValue(undefined),
			},
			onChanged: { addListener: vi.fn() },
		},
		runtime: {
			sendMessage: vi.fn().mockResolvedValue(false),
			getURL: vi.fn((path: string) => `moz-extension://test/${path}`),
		},
		management: {
			get: vi.fn().mockRejectedValue(new Error('not installed')),
		},
		bookmarks: {
			get: vi.fn().mockResolvedValue([{ id: 'bm1', url: 'https://bookmark.example.com', title: 'Bookmark' }]),
		},
	}
}

function makeTcLayer(extensionId: string | null = null, iconUrl: string | null = null): TcLayer {
	return {
		extensionId,
		iconUrl,
		isPresent: vi.fn().mockReturnValue(extensionId !== null),
		initialize: vi.fn().mockResolvedValue(undefined),
		isTempContainer: vi.fn().mockResolvedValue(false),
		createTempContainer: vi.fn().mockResolvedValue({ id: 50, index: 1 }),
		cleanupOrphanedTabs: vi.fn().mockResolvedValue(undefined),
	}
}

function makeTabReopener(): TabReopener {
	return {
		reopen: vi.fn().mockResolvedValue(undefined),
	}
}

const defaultSettings = {
	prioritizeReopen: false,
	suppressIsolationInfo: false,
}

const tab: Tab = {
	id: 1,
	url: 'https://example.com',
	index: 0,
	cookieStoreId: 'firefox-default',
	windowId: 1,
}

const containers = [
	{ name: 'Work', cookieStoreId: 'firefox-container-1', icon: 'briefcase', color: 'blue' },
	{ name: 'Personal', cookieStoreId: 'firefox-container-2', icon: 'fingerprint', color: 'green' },
]

// ---------------------------------------------------------------------------
// Tab context menu (existing F1/F2 behaviour)
// ---------------------------------------------------------------------------

describe('MenuHandlerImpl.buildMenus', () => {
	let browserApi: BrowserApi
	let tcLayer: TcLayer
	let tabReopener: TabReopener

	beforeEach(() => {
		browserApi = makeBrowserApi()
		tcLayer = makeTcLayer()
		tabReopener = makeTabReopener()
	})

	it('with prioritizeReopen=false creates "Open in New Container Tab" parent menu item', async () => {
		const handler = new MenuHandlerImpl({ browserApi, tcLayer, tabReopener })
